class WorkspaceHost:Panel {
 public readonly List<Panel> TabPages=new List<Panel>();
 public event EventHandler SelectedIndexChanged;
 public Panel SelectedTab {get{return TabPages.Count==0?null:TabPages[selected];}}
 int selected;
 public void Display(int index){if(index<0||index>=TabPages.Count)return;selected=index;SuspendLayout();foreach(var p in TabPages){if(p.Parent!=this){p.Dock=DockStyle.Fill;Controls.Add(p);}p.Visible=p==SelectedTab;}SelectedTab.BringToFront();ResumeLayout();if(SelectedIndexChanged!=null)SelectedIndexChanged(this,EventArgs.Empty);}
}

class Surface:Panel {
 public Color Stroke=Color.FromArgb(48,55,66);public int Radius=10;
 public Surface(){DoubleBuffered=true;BackColor=Color.FromArgb(23,28,35);Padding=new Padding(18);}
 public static GraphicsPath Shape(Rectangle r,int radius){int d=radius*2;var p=new GraphicsPath();p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var p=Shape(new Rectangle(0,0,Width-1,Height-1),Radius))using(var pen=new Pen(Stroke))e.Graphics.DrawPath(pen,p);}
}

