static class Glyphs {
 public static void Draw(Graphics g,Rectangle r,int type,Color color){g.SmoothingMode=SmoothingMode.AntiAlias;using(var p=new Pen(color,1.65f)){float x=r.X,y=r.Y,w=r.Width,h=r.Height;switch(type%10){
 case 0:g.DrawEllipse(p,x+w*.32f,y,w*.36f,h*.36f);g.DrawArc(p,x+w*.08f,y+h*.43f,w*.84f,h*.65f,180,180);break;
 case 1:g.DrawRectangle(p,x+w*.12f,y+h*.24f,w*.76f,h*.67f);g.DrawArc(p,x+w*.3f,y,w*.4f,h*.5f,180,180);g.DrawLine(p,x+w*.12f,y+h*.48f,x+w*.88f,y+h*.48f);break;
 case 2:g.DrawLine(p,x,y+h,x+w,y);g.DrawLine(p,x+w*.2f,y+h*.55f,x+w*.5f,y+h*.85f);g.DrawLine(p,x+w*.65f,y,x+w,y+h*.35f);break;
 case 3:g.DrawPolygon(p,new[]{new PointF(x+w*.5f,y),new PointF(x+w,y+h*.25f),new PointF(x+w,y+h*.75f),new PointF(x+w*.5f,y+h),new PointF(x,y+h*.75f),new PointF(x,y+h*.25f)});g.DrawLine(p,x,y+h*.25f,x+w*.5f,y+h*.5f);g.DrawLine(p,x+w,y+h*.25f,x+w*.5f,y+h*.5f);g.DrawLine(p,x+w*.5f,y+h*.5f,x+w*.5f,y+h);break;
 case 4:g.DrawPolygon(p,new[]{new PointF(x,y+h*.2f),new PointF(x+w*.3f,y),new PointF(x+w*.5f,y+h*.2f),new PointF(x+w*.7f,y),new PointF(x+w,y+h*.2f),new PointF(x+w*.8f,y+h*.5f),new PointF(x+w*.75f,y+h),new PointF(x+w*.25f,y+h),new PointF(x+w*.2f,y+h*.5f)});break;
 case 5:g.DrawPolygon(p,new[]{new PointF(x+w*.5f,y),new PointF(x+w*.15f,y+h*.55f),new PointF(x+w*.48f,y+h*.55f),new PointF(x+w*.3f,y+h),new PointF(x+w*.9f,y+h*.36f),new PointF(x+w*.55f,y+h*.36f)});break;
 case 6:g.DrawPolygon(p,new[]{new PointF(x+w*.5f,y),new PointF(x+w,y+h*.4f),new PointF(x+w*.5f,y+h),new PointF(x,y+h*.4f)});g.DrawLine(p,x+w*.5f,y,x+w*.5f,y+h);break;
 case 7:g.DrawRectangle(p,x+w*.15f,y,w*.7f,h);g.DrawLine(p,x+w*.3f,y+h*.3f,x+w*.7f,y+h*.3f);g.DrawLine(p,x+w*.3f,y+h*.55f,x+w*.7f,y+h*.55f);break;
 case 8:g.DrawRectangle(p,x,y+h*.15f,w,h*.7f);g.DrawLine(p,x,y+h*.15f,x+w*.5f,y+h*.55f);g.DrawLine(p,x+w,y+h*.15f,x+w*.5f,y+h*.55f);break;
 default:g.DrawEllipse(p,x,y,w,h);g.DrawLine(p,x+w*.5f,y+h*.2f,x+w*.5f,y+h*.55f);g.DrawLine(p,x+w*.5f,y+h*.55f,x+w*.75f,y+h*.7f);break;
 }}}
 public static Image Bitmap(int type,Color color){var b=new Bitmap(32,32);using(var g=Graphics.FromImage(b))Draw(g,new Rectangle(6,6,20,20),type,color);return b;}
}

class ArtResult {public Image Image;public int Rarity=-1;}
class ClientArt:IDisposable {
 readonly Dictionary<uint,ArtResult> cache=new Dictionary<uint,ArtResult>();
 readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);Process worker;bool unavailable,disposed;string root;
 public ClientArt(string root){this.root=root;}
 public static Color Rarity(int value){Color[] colors={Color.FromArgb(229,237,245),Color.FromArgb(104,213,237),Color.FromArgb(185,130,255),Color.FromArgb(248,115,237),Color.FromArgb(255,194,71),Color.FromArgb(255,115,115),Color.FromArgb(255,131,56),Color.FromArgb(244,190,104),Color.FromArgb(104,220,197)};return value>=0&&value<colors.Length?colors[value]:Color.FromArgb(171,179,188);}
 public async Task<ArtResult> Get(uint id){await gate.WaitAsync();try{ArtResult found;if(cache.TryGetValue(id,out found))return found;if(disposed||unavailable)return new ArtResult();var result=await Task.Run(()=>Read(id));cache[id]=result;return result;}finally{gate.Release();}}
 ArtResult Read(uint id){try{if(worker==null){string module=Path.Combine(root,"02_服务端","server","work","dfo-lan");if(!Directory.Exists(module))module=Path.Combine(root,"server","work","dfo-lan");string pvf=Path.GetFullPath(Path.Combine(module,"..","client-build","Script.inner.pvf"));string packs=Path.Combine(root,"01_客户端","DFO","ImagePacks2");if(!Directory.Exists(packs))packs=Path.Combine(root,"client","ImagePacks2");if(!File.Exists(pvf)||!Directory.Exists(packs)){unavailable=true;return new ArtResult();}string exe=Program.ExtractBackend();worker=new Process{StartInfo=new ProcessStartInfo(exe,"-desktop-icons \""+packs+"\" -pvf-archive \""+pvf+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=new System.Text.UTF8Encoding(false),StandardErrorEncoding=new System.Text.UTF8Encoding(false)}};worker.Start();worker.BeginErrorReadLine();var ready=Program.Parse(worker.StandardOutput.ReadLine());if(!Program.Bool(ready,"ready"))throw new Exception("Asset reader not ready");}worker.StandardInput.WriteLine(Program.Json.Serialize(new{id}));worker.StandardInput.Flush();var row=Program.Parse(worker.StandardOutput.ReadLine());var result=new ArtResult();if(row.ContainsKey("rarity"))result.Rarity=Convert.ToInt32(row["rarity"]);string png=Program.Str(row,"png");if(png!=""){using(var stream=new MemoryStream(Convert.FromBase64String(png)))using(var image=Image.FromStream(stream))result.Image=new Bitmap(image);}return result;}catch{unavailable=true;return new ArtResult();}}
 public void Dispose(){disposed=true;if(worker!=null){try{if(!worker.HasExited)worker.Kill();}catch{}worker.Dispose();}/* Controls can still paint cached images while their parent is closing. */}
}

class ItemTile:Button {
 public string ItemName,Caption,Quantity;public uint ID;public ArtResult Art=new ArtResult();public bool Selected;bool hover;
 public ItemTile(){DoubleBuffered=true;Size=new Size(160,158);Margin=new Padding(0,0,12,12);Cursor=Cursors.Hand;FlatStyle=FlatStyle.Flat;AccessibleRole=AccessibleRole.PushButton;}
 protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}
 protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
 protected override void OnGotFocus(EventArgs e){Invalidate();base.OnGotFocus(e);}
 protected override void OnLostFocus(EventArgs e){Invalidate();base.OnLostFocus(e);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Parent.BackColor);var r=new Rectangle(0,0,Width-1,Height-1);using(var p=Surface.Shape(r,8)){using(var b=new SolidBrush(Selected?Color.FromArgb(48,43,33):hover?Color.FromArgb(32,40,52):Color.FromArgb(19,25,34)))g.FillPath(b,p);using(var pen=new Pen(Selected||Focused?Color.FromArgb(232,189,105):hover?Color.FromArgb(85,97,117):Color.FromArgb(48,55,66)))g.DrawPath(pen,p);}var muted=Color.FromArgb(145,156,170);TextRenderer.DrawText(g,Caption,Font,new Rectangle(12,9,Width-24,18),muted,TextFormatFlags.EndEllipsis);var icon=new Rectangle(13,34,44,44);using(var b=new SolidBrush(Color.FromArgb(28,35,45)))g.FillRectangle(b,icon);using(var p=new Pen(Color.FromArgb(67,73,86)))g.DrawRectangle(p,icon);if(Art.Image!=null){g.InterpolationMode=InterpolationMode.NearestNeighbor;int w=Math.Min(40,Art.Image.Width),h=Math.Min(40,Art.Image.Height);g.DrawImage(Art.Image,new Rectangle(icon.X+(44-w)/2,icon.Y+(44-h)/2,w,h));}else Glyphs.Draw(g,new Rectangle(24,45,23,23),3,muted);if(Quantity!="")TextRenderer.DrawText(g,Quantity,Font,new Rectangle(66,54,Width-78,22),Color.FromArgb(232,189,105),TextFormatFlags.Right);TextRenderer.DrawText(g,ItemName,Font,new Rectangle(12,85,Width-24,39),ClientArt.Rarity(Art.Rarity),TextFormatFlags.WordBreak|TextFormatFlags.EndEllipsis);using(var small=new Font("Segoe UI",8))TextRenderer.DrawText(g,"#"+ID,small,new Rectangle(12,Height-20,Width-24,18),muted,TextFormatFlags.Left);}
}

class ItemBoard:FlowLayoutPanel {
 public Action<Dictionary<string,object>> Pick;public Func<uint,Task<ArtResult>> GetArt;
 readonly List<ItemTile> tiles=new List<ItemTile>();int generation;
 public ItemBoard(){NativeTheme.Dark(this);Dock=DockStyle.Fill;AutoScroll=true;BackColor=Color.FromArgb(23,28,35);DoubleBuffered=true;Padding=new Padding(0,4,0,0);}
 protected override void OnSizeChanged(EventArgs e){base.OnSizeChanged(e);foreach(Control child in Controls)if(child is EmptyItems)child.Size=new Size(Math.Max(100,ClientSize.Width-8),Math.Max(30,ClientSize.Height-12));}
 public void Mark(Dictionary<string,object> row){foreach(var tile in tiles){tile.Selected=Object.ReferenceEquals(tile.Tag,row);tile.Invalidate();}}
 public void SetRows(IEnumerable<Dictionary<string,object>> rows,string idKey,string captionKey,string quantityKey){generation++;int current=generation;SuspendLayout();foreach(var old in tiles)old.Dispose();tiles.Clear();Controls.Clear();foreach(var row in rows){var tile=new ItemTile{ID=Convert.ToUInt32(row[idKey]),ItemName=Program.Str(row,"name"),Caption=captionKey=="container"?GMForm.ContainerText(Program.Str(row,captionKey))+" · "+Program.Str(row,"slot"):Program.Str(row,captionKey),Quantity=quantityKey==""?"":"×"+Program.Str(row,quantityKey),Tag=row};tile.AccessibleName=tile.ItemName+" #"+tile.ID;tile.Click+=(s,e)=>{foreach(var t in tiles){t.Selected=t==tile;t.Invalidate();}if(Pick!=null)Pick(row);};tiles.Add(tile);Controls.Add(tile);LoadArt(tile,current);}AutoScroll=tiles.Count>0;if(tiles.Count==0)Controls.Add(new EmptyItems{Size=new Size(Math.Max(100,ClientSize.Width-8),Math.Max(30,ClientSize.Height-12)),Margin=new Padding(0),Font=Font});ResumeLayout();}
 async void LoadArt(ItemTile tile,int current){if(GetArt==null)return;var result=await GetArt(tile.ID);if(IsDisposed||current!=generation||tile.IsDisposed)return;tile.Art=result;tile.Invalidate();}
}

