 Surface Card(string title,string hint,params Control[] controls){var card=new Surface{Width=290,Height=222,Margin=new Padding(0,0,16,16),Padding=new Padding(20)};var stack=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,FlowDirection=FlowDirection.TopDown,Margin=new Padding(0)};card.Controls.Add(stack);var heading=Label(title,13);heading.Font=new Font(Font.FontFamily,13,FontStyle.Bold);heading.Margin=new Padding(0,0,0,7);stack.Controls.Add(heading);var note=Label(hint);note.ForeColor=Muted;note.Margin=new Padding(0,0,0,10);stack.Controls.Add(note);foreach(var c in controls)stack.Controls.Add(c);card.SizeChanged+=(s,e)=>{note.MaximumSize=new Size(card.ClientSize.Width-42,34);foreach(Control child in stack.Controls){if(child is Button){child.AutoSize=false;child.Width=card.ClientSize.Width-42;}var flow=child as FlowLayoutPanel;if(flow!=null)foreach(Control input in flow.Controls)if(input is NumericUpDown)input.Width=card.ClientSize.Width-54;}};return card;}
