 static void SelectTagged(DataGridView grid,Dictionary<string,object> item){foreach(DataGridViewRow row in grid.Rows)if(Object.ReferenceEquals(row.Tag,item)){grid.ClearSelection();row.Selected=true;grid.CurrentCell=row.Cells[0];break;}}
 void RenderInventoryTiles(){var rows=inventoryGrid.Rows.Cast<DataGridViewRow>().Where(x=>x.Tag!=null).Select(x=>(Dictionary<string,object>)x.Tag);inventoryBoard.SetRows(rows,"template","container","amount");}
